// This file is generated by AI.

// LSP 客户端单例: 在浏览器 WebSocket 上实现最小 JSON-RPC, 桥接内置 WebGAL LSP。
//
// 关键点:
// * 服务端 -> 客户端使用二进制帧 (ArrayBuffer/Blob), 需解码为文本。
// * 文本同步为 FULL 模式: 每次 didChange 发送完整文档。
// * 必须实现 `workspace/fs/stat`, `workspace/fs/readDirectory` 和
//   `workspace/fs/readFile` 三个反向请求 (服务端依赖它们扫描项目)。
// * 接受 `client/registerCapability` (服务端在 initialized 时注册文件监控)。

import { invoke } from '@tauri-apps/api/core';

import { fs } from '../lib/fs';
import { fromUri, toUri } from '../lib/uri';
import { previewClient } from '../preview/client';
import { useAppStore } from '../state/store';
import { startWatching, stopWatching } from './watch';

export interface LspPosition {
  line: number;
  character: number;
}

export interface LspRange {
  start: LspPosition;
  end: LspPosition;
}

export interface LspTextEdit {
  range: LspRange;
  newText: string;
}

export interface LspInlayHint {
  position: LspPosition;
  label: string | { value: string; tooltip?: string | { kind: string; value: string } }[];
  kind?: number;
  textEdits?: LspTextEdit[];
  tooltip?: string | { kind: string; value: string };
  paddingLeft?: boolean;
  paddingRight?: boolean;
}

export interface LspDiagnostic {
  range: LspRange;
  severity: number;
  message: string;
  /** 诊断错误码 (如 WG001), 服务端以字符串或数字发送 */
  code?: number | string;
  source?: string;
}

export interface LspHover {
  contents: string | { kind: string; value: string }[] | { kind: string; value: string };
  range?: LspRange;
}

export interface LspLocation {
  uri: string;
  range: LspRange;
}

export interface LspDocumentLink {
  range: LspRange;
  /** 链接目标 URI (无法解析时可能缺省) */
  target?: string;
  tooltip?: string;
}

/** `textDocument/prepareRename` 的结果 (RangeWithPlaceholder) */
export interface LspRenameLocation {
  range: LspRange;
  /** 当前符号名, 作为输入框的占位内容 */
  placeholder: string;
}

/** `textDocument/rename` 的结果: 按文件 URI 分组的文本编辑 */
export interface LspWorkspaceEdit {
  changes?: Record<string, LspTextEdit[]>;
}

export interface LspCompletionItem {
  label: string;
  kind?: number;
  detail?: string;
  documentation?: string | { kind: string; value: string };
  /** LSP labelDetails: description 为条目右部的详细描述 */
  labelDetails?: { detail?: string | null; description?: string | null };
  textEdit?: { range: LspRange; newText: string } | { newText: string };
  insertText?: string;
  /** 1 = PlainText, 2 = Snippet */
  insertTextFormat?: number;
}

interface JsonRpcRequest {
  jsonrpc: '2.0';
  id: number | string;
  method: string;
  params?: unknown;
}

interface JsonRpcResponse {
  jsonrpc: '2.0';
  id: number | string;
  result?: unknown;
  error?: { code: number; message: string };
}

interface JsonRpcNotification {
  jsonrpc: '2.0';
  method: string;
  params?: unknown;
}

type NotificationHandler = (params: unknown) => void;
type RequestHandler = (params: unknown) => Promise<unknown> | unknown;

/**
 * 一个请求超过这么久还没答复, 就认为语言服务在忙 (而不是"就绪")。
 *
 * 处理大批文件变更时语言服务会长时间不给任何答复 —— 连接还在、状态还是 ready, 编辑器
 * 底部却写着"就绪", 用户看到的就是"卡死了还骗我说没事"(issue #25)。这里按**响应延迟**
 * 判断忙闲: 只要还有请求超时未答就显示"响应缓慢", 答复一到就自动恢复。
 */
const SLOW_REQUEST_MS = 2000;

export class LspClient {
  private socket: WebSocket | null = null;
  private nextId = 1;
  private pending = new Map<
    number | string,
    { resolve: (v: unknown) => void; reject: (e: Error) => void; sentAt: number; sent: boolean }
  >();
  private notificationHandlers = new Map<string, NotificationHandler[]>();
  private requestHandlers = new Map<string, RequestHandler>();
  private diagnosticsListeners = new Set<(uri: string, diags: LspDiagnostic[]) => void>();
  private started = false;
  private initialized = false;
  /**
   * 握手 (initialize 往返 + initialized 通知) 是否已完成 —— 服务端在那之前不会处理任何
   * 请求与通知 (tower-lsp 直接回 -32002 或直接丢弃), 因此出站消息在此之前只能先攒着。
   */
  private ready = false;
  /** 握手完成前攒下的出站消息, 见 `sendRaw` */
  private outbox: unknown[] = [];
  /** 后端压根没起来 (`start_server` 失败): 之后的请求当场失败, 不排在缓冲里假装还能连上 */
  private unreachable: Error | null = null;
  private pendingFolders: { added: string[]; removed: string[] } | null = null;
  private frameBuffer: Uint8Array = new Uint8Array(0);
  /** 忙闲检查的定时器 (同一时刻只留一个) */
  private activityTimer: ReturnType<typeof setTimeout> | null = null;

  /** 文件监听: 服务器通过 client/registerCapability 注册 didChangeWatchedFiles 后启用 */
  private watchedEnabled = false;
  private watcherRoots: string[] = [];

  private decodeData(data: unknown): void {
    let bytes: Uint8Array;
    if (typeof data === 'string') {
      bytes = new TextEncoder().encode(data);
    } else if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    } else if (data instanceof Blob) {
      void data.arrayBuffer().then((buf) => this.decodeData(buf));
      return;
    } else if (Array.isArray(data)) {
      void new Blob(data).arrayBuffer().then((buf) => this.decodeData(buf));
      return;
    } else {
      return;
    }
    this.appendBytes(bytes);
    this.extractFrames();
  }

  /** 追加字节到缓冲 (合并为新的 Uint8Array, 避免大数组展开导致的调用栈溢出)。 */
  private appendBytes(bytes: Uint8Array): void {
    if (this.frameBuffer.length === 0) {
      this.frameBuffer = bytes;
      return;
    }
    const merged = new Uint8Array(this.frameBuffer.length + bytes.length);
    merged.set(this.frameBuffer, 0);
    merged.set(bytes, this.frameBuffer.length);
    this.frameBuffer = merged;
  }

  /** 从字节缓冲中解析 Content-Length 帧, 逐条交给 handleText。 */
  private extractFrames(): void {
    const decoder = new TextDecoder();
    for (;;) {
      const headerEnd = this.indexOfSequence([13, 10, 13, 10]);
      if (headerEnd === -1) break;
      const header = decoder.decode(this.frameBuffer.subarray(0, headerEnd));
      const match = /Content-Length:\s*(\d+)/i.exec(header);
      const bodyStart = headerEnd + 4;
      if (!match) {
        this.frameBuffer = this.frameBuffer.subarray(bodyStart);
        continue;
      }
      const length = Number(match[1]);
      if (this.frameBuffer.length < bodyStart + length) break; // 帧不完整, 等待更多字节
      const body = decoder.decode(this.frameBuffer.subarray(bodyStart, bodyStart + length));
      this.frameBuffer = this.frameBuffer.subarray(bodyStart + length);
      this.handleText(body);
    }
  }

  private indexOfSequence(needle: number[]): number {
    const bytes = this.frameBuffer;
    outer: for (let i = 0; i <= bytes.length - needle.length; i++) {
      for (let j = 0; j < needle.length; j++) {
        if (bytes[i + j] !== needle[j]) continue outer;
      }
      return i;
    }
    return -1;
  }

  private handleText(text: string): void {
    let msg: JsonRpcRequest | JsonRpcResponse | JsonRpcNotification;
    try {
      msg = JSON.parse(text) as JsonRpcRequest | JsonRpcResponse | JsonRpcNotification;
    } catch {
      return;
    }

    if ('method' in msg && 'id' in msg) {
      // 服务端发来的请求
      void this.handleServerRequest(msg as JsonRpcRequest);
    } else if ('id' in msg && ('result' in msg || 'error' in msg)) {
      this.handleResponse(msg as JsonRpcResponse);
    } else if ('method' in msg) {
      this.handleNotification(msg as JsonRpcNotification);
    }
  }

  private async handleServerRequest(msg: JsonRpcRequest): Promise<void> {
    const handler = this.requestHandlers.get(msg.method);
    let result: unknown = null;
    if (handler) {
      try {
        result = await handler(msg.params);
      } catch (e) {
        // 应答服务端反向请求: 绕开缓冲 —— 它正等着这个结果
        this.writeFrame({
          jsonrpc: '2.0',
          id: msg.id,
          error: { code: -32603, message: String(e) },
        });
        return;
      }
    }
    this.writeFrame({ jsonrpc: '2.0', id: msg.id, result });
  }

  private handleResponse(msg: JsonRpcResponse): void {
    const pending = this.pending.get(msg.id);
    if (!pending) return;
    this.pending.delete(msg.id);
    if (msg.error) pending.reject(new Error(msg.error.message));
    else pending.resolve(msg.result);
    // 答复到达即重新判断忙闲: 没有超时未答的请求就恢复正常显示
    this.refreshActivity();
  }

  private handleNotification(msg: JsonRpcNotification): void {
    if (msg.method === 'textDocument/publishDiagnostics') {
      const p = msg.params as { uri: string; diagnostics: LspDiagnostic[] };
      const diagnostics = p.diagnostics ?? [];
      this.diagnosticsListeners.forEach((cb) => cb(p.uri, diagnostics));
    }
    this.notificationHandlers.get(msg.method)?.forEach((h) => h(msg.params));
  }

  /**
   * 发送一条出站消息。
   *
   * 连接就绪之前**不能**直接写 socket, 也不能丢掉: 旧实现这时直接 `return`, 于是启动期间
   * 发出的 `didOpen` 与语义高亮请求被静默吞掉 —— 请求的 Promise 再也没有结果, Monaco 的
   * provider 就此停在那里 (场景一直不着色, 直到用户切标签页重建编辑器)。现在改为按序缓冲,
   * 握手完成后一次性冲出 (`flushOutbox`), 顺序即语义。
   */
  private sendRaw(obj: unknown): void {
    if (this.unreachable) return; // 后端没起来: 通知留着也没人能收
    if (this.ready && this.socket && this.socket.readyState === WebSocket.OPEN) {
      this.writeFrame(obj);
      return;
    }
    this.outbox.push(obj);
  }

  /**
   * 真正写一帧。
   *
   * 握手消息 (`initialize` / `initialized`) 与"对服务端反向请求的应答"走这里 —— 它们
   * 必须绕开缓冲, 否则缓冲永远等不到释放它的那条消息。
   */
  private writeFrame(obj: unknown): void {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) return;
    // 缓冲期间不计入响应延迟: 请求真正发出时才起算, 否则状态栏会误报"响应缓慢"
    const id = (obj as { id?: number | string }).id;
    if (id !== undefined) {
      const pending = this.pending.get(id);
      if (pending) {
        pending.sentAt = Date.now();
        pending.sent = true;
      }
    }
    // LSP stdio 帧协议, 以二进制帧发送
    // (ws_stream_tungstenite 只支持二进制消息, 文本消息会导致连接被关闭)
    const json = JSON.stringify(obj);
    const encoder = new TextEncoder();
    const jsonBytes = encoder.encode(json);
    const headerBytes = encoder.encode(`Content-Length: ${jsonBytes.length}\r\n\r\n`);
    const frame = new Uint8Array(headerBytes.length + jsonBytes.length);
    frame.set(headerBytes, 0);
    frame.set(jsonBytes, headerBytes.length);
    this.socket.send(frame);
  }

  /** 握手完成后按序送出缓冲的消息。 */
  private flushOutbox(): void {
    const queued = this.outbox;
    this.outbox = [];
    for (const obj of queued) this.writeFrame(obj);
  }

  sendRequest(method: string, params?: unknown): Promise<unknown> {
    return this.dispatch(method, params, false);
  }

  /** 发起一个请求; `immediate` 为真时绕开缓冲 (只有握手请求这么做)。 */
  private dispatch(method: string, params: unknown, immediate: boolean): Promise<unknown> {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      // 后端没起来时不再排队: 让调用方立刻拿到失败, 而不是等一个不会到来的握手
      if (this.unreachable && !immediate) {
        reject(this.unreachable);
        return;
      }
      this.pending.set(id, { resolve, reject, sentAt: Date.now(), sent: false });
      const request = { jsonrpc: '2.0', id, method, params };
      if (immediate) this.writeFrame(request);
      else this.sendRaw(request);
      this.scheduleActivityCheck();
    });
  }

  /**
   * 安排一次忙闲检查。
   *
   * 用"延迟"而不是"有没有在跑"判断: 语言服务是被动应答的, 只有请求迟迟不回才说明它忙。
   */
  private scheduleActivityCheck(): void {
    if (this.activityTimer) return;
    this.activityTimer = setTimeout(() => {
      this.activityTimer = null;
      this.refreshActivity();
    }, SLOW_REQUEST_MS);
  }

  /** 按"还有多少请求超时未答"更新状态栏里的忙闲提示。 */
  private refreshActivity(): void {
    const now = Date.now();
    let slow = 0;
    for (const entry of this.pending.values()) {
      // 还没发出去的请求不算"服务端没答复": 那是在等握手, 不是语言服务慢
      if (!entry.sent) continue;
      if (now - entry.sentAt >= SLOW_REQUEST_MS) slow += 1;
    }
    const store = useAppStore.getState();
    if (slow > 0) {
      store.setLspActivity(`语言服务响应缓慢：${slow} 个请求仍未答复（可能正在处理大量文件变更）`);
    } else if (store.lspActivity) {
      store.setLspActivity(null);
    }
  }

  sendNotification(method: string, params?: unknown): void {
    this.sendRaw({ jsonrpc: '2.0', method, params });
  }

  onNotification(method: string, handler: NotificationHandler): void {
    const list = this.notificationHandlers.get(method) ?? [];
    list.push(handler);
    this.notificationHandlers.set(method, list);
  }

  onRequest(method: string, handler: RequestHandler): void {
    this.requestHandlers.set(method, handler);
  }

  onDiagnostics(cb: (uri: string, diags: LspDiagnostic[]) => void): void {
    this.diagnosticsListeners.add(cb);
  }

  // -------- 生命周期 --------

  async start(): Promise<void> {
    if (this.started) return;
    this.started = true;
    const store = useAppStore.getState();
    store.setLspStatus('connecting');

    // 反向 FS 请求: 协议资源统一使用规范 URI, 本地 FS 调用前才转换为路径。
    this.onRequest('workspace/fs/stat', async (params) => {
      const { uri } = params as { uri: string };
      return fs.stat(fromUri(uri));
    });
    this.onRequest('workspace/fs/readDirectory', async (params) => {
      const { uri } = params as { uri: string };
      const entries = await fs.readDir(fromUri(uri));
      return entries.map((entry) => ({
        uri: `${uri.replace(/\/$/, '')}/${encodeURIComponent(entry.name)}`,
        name: entry.name,
        type: entry.isDirectory ? 'directory' : 'file',
      }));
    });
    this.onRequest('workspace/fs/readFile', async (params) => {
      const { uri, encoding } = params as { uri: string; encoding?: 'utf-8' | 'base64' };
      if (encoding === 'base64') {
        const bytes = await fs.readBytes(fromUri(uri));
        let binary = '';
        for (const byte of bytes) binary += String.fromCharCode(byte);
        return { content: btoa(binary), encoding: 'base64' };
      }
      return { content: await fs.readText(fromUri(uri)), encoding: 'utf-8' };
    });
    this.onRequest('client/registerCapability', (params) => {
      this.handleRegisterCapability(params);
      return null;
    });

    // 诊断回写: LSP 推送 publishDiagnostics -> 写入 store 供编辑器 lint 使用
    this.onDiagnostics((uri, diagnostics) => {
      useAppStore.getState().setDiagnostics(fromUri(uri), diagnostics);
    });

    let port: number;
    try {
      port = await invoke<number>('start_server');
    } catch (e) {
      store.setLspStatus('error', String(e));
      // 连接根本没起来: 缓冲里的请求必须当场结算, 否则调用方永远等不到结果 (它们原本
      // 会一直排在缓冲里等一个不会到来的握手)
      this.unreachable = new Error(`语言服务未启动: ${String(e)}`);
      this.rejectAllPending(this.unreachable, true);
      this.outbox = [];
      return;
    }

    await this.connect(port);
  }

  private connect(port: number): Promise<void> {
    return new Promise((resolve) => {
      const socket = new WebSocket(`ws://127.0.0.1:${port}`);
      socket.binaryType = 'arraybuffer';
      this.socket = socket;

      socket.onopen = () => {
        void (async () => {
          try {
            await this.dispatch(
              'initialize',
              {
                processId: null,
                rootUri: null,
                capabilities: {
                  workspace: { workspaceFolders: true },
                  textDocument: {
                    synchronization: { dynamicRegistration: true, didSave: false },
                  },
                },
                workspaceFolders: [],
              },
              true
            );
            // `initialized` 同样绕开缓冲: 缓冲里的消息正是在等它发出去
            this.writeFrame({ jsonrpc: '2.0', method: 'initialized', params: {} });
            this.initialized = true;
            this.ready = true;
            this.unreachable = null; // 重连成功后重新可以排队
            /* 顺序即语义, 服务端按收到的顺序处理:
             * 1. 工作区变更 (它决定服务端何时开始扫描项目);
             * 2. 启动期间攒下的 didOpen / didChange / 语义高亮请求;
             * 3. 重连或恢复时按当前内容补发的 didOpen。
             */
            if (this.pendingFolders) {
              const pending = this.pendingFolders;
              this.pendingFolders = null;
              this.changeWorkspaceFolders(pending.added, pending.removed);
            }
            this.flushOutbox();
            useAppStore.getState().setLspStatus('ready');
            this.reopenDocuments();
          } catch (e) {
            // 握手失败: 这条连接不会有任何结果, 之后的请求立刻失败总好过永远排队
            const error = new Error(`语言服务握手失败: ${String(e)}`);
            useAppStore.getState().setLspStatus('error', error.message);
            this.unreachable = error;
            this.rejectAllPending(error, true);
            this.outbox = [];
          }
          resolve();
        })();
      };

      socket.onmessage = (ev) => this.decodeData(ev.data);
      socket.onclose = () => {
        if (this.socket !== socket) return; // 已由新连接接管
        this.socket = null;
        this.ready = false;
        this.initialized = false;
        // 请求当场结算 (没人能再收它们了); 通知保留 —— 重连后必须补发文档与工作区状态
        this.rejectAllPending(new Error('LSP 连接已断开'), true);
        useAppStore.getState().setLspStatus('error', 'LSP 连接已断开，正在重连…');
        // 后端支持重复接入, 稍后自动重连并恢复文档
        setTimeout(() => {
          if (this.started && !this.socket) void this.connect(port);
        }, 1000);
      };
      socket.onerror = () => {
        /* onclose 会随后触发 */
      };
    });
  }

  /**
   * 结算所有未答复的请求。
   *
   * `queued` 为真时把还排在缓冲里的**请求**一并结算并移出缓冲: 连接已经没了, 它们发不出去,
   * 留着只会让调用方永远等下去。缓冲里的**通知**保留 —— 那是文档与工作区的状态更新, 重连
   * 之后必须照原样补发。
   */
  private rejectAllPending(error: Error, queued = false): void {
    for (const { reject } of this.pending.values()) reject(error);
    this.pending.clear();
    if (queued) {
      this.outbox = this.outbox.filter((obj) => (obj as { id?: unknown }).id === undefined);
    }
    // 连接都没了, "响应缓慢"不再是有效信息 (状态会切到"错误/重连中")
    useAppStore.getState().setLspActivity(null);
  }

  /** 重连后恢复已打开文档的同步状态。 */
  private reopenDocuments(): void {
    for (const doc of useAppStore.getState().documents) {
      if (doc.isScene) this.openDocument(doc.path, doc.content);
    }
  }

  // -------- 文档同步 (FULL) --------

  openDocument(path: string, text: string): void {
    this.sendNotification('textDocument/didOpen', {
      textDocument: {
        uri: toUri(path),
        languageId: 'webgal',
        version: 1,
        text,
      },
    });
  }

  changeDocument(path: string, text: string, version: number): void {
    this.sendNotification('textDocument/didChange', {
      textDocument: { uri: toUri(path), version },
      contentChanges: [{ text }],
    });
  }

  closeDocument(path: string): void {
    this.sendNotification('textDocument/didClose', {
      textDocument: { uri: toUri(path) },
    });
  }

  changeWorkspaceFolders(added: string[], removed: string[]): void {
    if (!this.initialized) {
      this.pendingFolders = { added, removed };
    } else {
      this.sendWorkspaceFolders(added, removed);
    }
    // 同步文件监听根目录 (无论初始化与否都记录)
    this.watcherRoots = [...this.watcherRoots.filter((r) => !removed.includes(r)), ...added];
    void this.syncWatcher();
  }

  private sendWorkspaceFolders(added: string[], removed: string[]): void {
    this.sendNotification('workspace/didChangeWorkspaceFolders', {
      event: {
        added: added.map((p) => ({ uri: toUri(p), name: toUri(p) })),
        removed: removed.map((p) => ({ uri: toUri(p), name: toUri(p) })),
      },
    });
  }

  // -------- 文件监听 (workspace/didChangeWatchedFiles) --------

  /** 解析服务器通过 client/registerCapability 注册的文件监听能力。 */
  private handleRegisterCapability(params: unknown): void {
    const registrations = (params as { registrations?: { method?: string }[] } | null)?.registrations ?? [];
    const hasWatched = registrations.some((r) => r.method === 'workspace/didChangeWatchedFiles');
    if (!hasWatched) return;
    this.watchedEnabled = true;
    void this.syncWatcher();
  }

  private async syncWatcher(): Promise<void> {
    if (this.watchedEnabled && this.watcherRoots.length > 0) {
      await startWatching(this.watcherRoots, (changes) => {
        if (changes.length === 0) return;
        this.sendNotification('workspace/didChangeWatchedFiles', {
          changes: changes.map((c) => ({ uri: toUri(c.path), type: c.type })),
        });
        // 模板文件变化 -> 通知预览重新拉取模板 (否则已运行引擎会缓存旧模板)
        const templateChanged = changes.some((c) =>
          c.path.replace(/\\/g, '/').toLowerCase().includes('/game/template/')
        );
        if (templateChanged) void previewClient.reloadTemplates();
      });
    } else {
      await stopWatching();
    }
  }

  // -------- 语言能力 --------

  async hover(path: string, position: LspPosition): Promise<LspHover | null> {
    const r = await this.sendRequest('textDocument/hover', {
      textDocument: { uri: toUri(path) },
      position,
    });
    return (r as LspHover | null) ?? null;
  }

  async completion(path: string, position: LspPosition): Promise<LspCompletionItem[] | null> {
    const r = await this.sendRequest('textDocument/completion', {
      textDocument: { uri: toUri(path) },
      position,
    });
    if (Array.isArray(r)) return r as LspCompletionItem[];
    if (r && typeof r === 'object' && 'items' in r) return (r as { items: LspCompletionItem[] }).items;
    return null;
  }

  async semanticTokens(path: string): Promise<number[] | null> {
    const r = await this.sendRequest('textDocument/semanticTokens/full', {
      textDocument: { uri: toUri(path) },
    });
    if (r && typeof r === 'object' && 'data' in r) return (r as { data: number[] }).data;
    return null;
  }

  async semanticTokensRange(path: string, range: LspRange): Promise<number[] | null> {
    const r = await this.sendRequest('textDocument/semanticTokens/range', {
      textDocument: { uri: toUri(path) },
      range,
    });
    if (r && typeof r === 'object' && 'data' in r) return (r as { data: number[] }).data;
    return null;
  }

  async inlayHints(path: string, range: LspRange): Promise<LspInlayHint[] | null> {
    const r = await this.sendRequest('textDocument/inlayHint', {
      textDocument: { uri: toUri(path) },
      range,
    });
    return (r as LspInlayHint[] | null) ?? null;
  }

  async formatting(path: string): Promise<LspTextEdit[] | null> {
    const r = await this.sendRequest('textDocument/formatting', {
      textDocument: { uri: toUri(path) },
      options: { tabSize: 2, insertSpaces: true },
    });
    return (r as LspTextEdit[] | null) ?? null;
  }

  async references(path: string, position: LspPosition): Promise<LspLocation[] | null> {
    const r = await this.sendRequest('textDocument/references', {
      textDocument: { uri: toUri(path) },
      position,
      context: { includeDeclaration: false },
    });
    return (r as LspLocation[] | null) ?? null;
  }

  async definition(path: string, position: LspPosition): Promise<LspLocation[] | null> {
    const r = await this.sendRequest('textDocument/definition', {
      textDocument: { uri: toUri(path) },
      position,
    });
    if (Array.isArray(r)) return r as LspLocation[];
    if (r && typeof r === 'object' && 'uri' in r) return [r as LspLocation];
    return null;
  }

  async documentLinks(path: string): Promise<LspDocumentLink[] | null> {
    const r = await this.sendRequest('textDocument/documentLink', {
      textDocument: { uri: toUri(path) },
    });
    return (r as LspDocumentLink[] | null) ?? null;
  }

  async prepareRename(path: string, position: LspPosition): Promise<LspRenameLocation | null> {
    const r = await this.sendRequest('textDocument/prepareRename', {
      textDocument: { uri: toUri(path) },
      position,
    });
    return (r as LspRenameLocation | null) ?? null;
  }

  async rename(path: string, position: LspPosition, newName: string): Promise<LspWorkspaceEdit | null> {
    const r = await this.sendRequest('textDocument/rename', {
      textDocument: { uri: toUri(path) },
      position,
      newName,
    });
    return (r as LspWorkspaceEdit | null) ?? null;
  }
}

export const lspClient = new LspClient();
